/* See mgba_bridge.h. Built against the unmodified mGBA core (mgba/ submodule, scripts/build-libmgba.sh). */
#include "mgba_bridge.h"

/* The library's own compile defines (M_CORE_GB, ENABLE_VFS, ENABLE_DIRECTORIES, ...) must come before any
 * mGBA header, or struct mCore's layout differs from the library's. Generated by scripts/build-libmgba.sh. */
#include <mgba-build-defines.h>
#include <mgba/core/cheats.h>
#include <mgba/core/config.h>
#include <mgba/core/core.h>
#include <mgba/core/interface.h>
#include <mgba/core/log.h>
#include <mgba/core/rewind.h>
#include <mgba/core/serialize.h>
#include <mgba-util/audio-buffer.h>
#include <mgba-util/configuration.h>
#include <mgba-util/vfs.h>

#ifdef M_CORE_GBA
#include <mgba/gba/interface.h>
#include <mgba/internal/gba/gba.h>
#endif
#ifdef M_CORE_GB
#include <mgba/gb/interface.h>
#include <mgba/internal/gb/gb.h>
#endif

#include <fcntl.h>
#include <stdarg.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define VIDEO_STRIDE 256
#define VIDEO_HEIGHT_MAX 224

struct GBPLux {
	struct GBALuminanceSource d;
	struct GBPCore* p;
	uint8_t value;
};

struct GBPRotation {
	struct mRotationSource d;
	struct GBPCore* p;
};

struct GBPRumble {
	struct mRumbleIntegrator d;
	struct GBPCore* p;
};

struct GBPCore {
	struct mCore* core;
	char* romPath;
	char* configPath;
	/* Only what the user set (saved to config.ini). The core's loadConfig copies resolved values, defaults
	 * included, into its own user layer, so that layer must not be what gets saved. */
	struct Configuration user;
	mColor* video;

	struct mCoreRewindContext rewind;
	bool rewindEnabled;
	int rewindInterval;
	int rewindCounter;
	bool rewinding;

	struct GBPLux lux;
	int luxLevel;
	struct GBPRotation rotation;
	volatile float tiltX;
	volatile float tiltY;
	struct GBPRumble rumble;
	volatile float rumbleLevel;
};

/* --- peripherals --- */

static void _luxSample(struct GBALuminanceSource* source) {
	struct GBPLux* lux = (struct GBPLux*) source;
	int value = 0x16;
	if (lux->p->luxLevel > 0) {
		value += GBA_LUX_LEVELS[lux->p->luxLevel - 1];
	}
	lux->value = 0xFF - value;
}

static uint8_t _luxRead(struct GBALuminanceSource* source) {
	return ((struct GBPLux*) source)->value;
}

static void _rotationSample(struct mRotationSource* source) {
	(void) source;
}

static int32_t _tilt(float value) {
	if (value > 1.f) {
		value = 1.f;
	} else if (value < -1.f) {
		value = -1.f;
	}
	return (int32_t) (value * 2.0e9f);
}

static int32_t _readTiltX(struct mRotationSource* source) {
	return _tilt(((struct GBPRotation*) source)->p->tiltX);
}

static int32_t _readTiltY(struct mRotationSource* source) {
	return _tilt(((struct GBPRotation*) source)->p->tiltY);
}

static int32_t _readGyroZ(struct mRotationSource* source) {
	(void) source;
	return 0;
}

static void _setRumble(struct mRumbleIntegrator* integrator, float level) {
	((struct GBPRumble*) integrator)->p->rumbleLevel = level;
}

/* --- logging: only errors reach stderr (the default logger prints every stub register write) --- */

static void _log(struct mLogger* logger, int category, enum mLogLevel level, const char* format, va_list args) {
	(void) logger;
	if (!(level & (mLOG_FATAL | mLOG_ERROR))) {
		return;
	}
	fprintf(stderr, "mGBA %s: ", mLogCategoryName(category));
	vfprintf(stderr, format, args);
	fputc('\n', stderr);
}

static struct mLogger _logger = { .log = _log };

/* --- lifecycle --- */

GBPCore* gbp_create(const char* romPath, const char* defaultsPath, const char* configPath) {
	mLogSetDefaultLogger(&_logger);
	struct mCore* core = mCoreFind(romPath);
	if (!core) {
		return NULL;
	}
	GBPCore* gbp = calloc(1, sizeof(*gbp));
	gbp->core = core;
	gbp->romPath = strdup(romPath);
	gbp->configPath = configPath ? strdup(configPath) : NULL;

	mCoreInitConfig(core, NULL);
	core->init(core);

	if (defaultsPath) {
		ConfigurationRead(&core->config.defaultsTable, defaultsPath);
	}
	ConfigurationInit(&gbp->user);
	if (configPath) {
		mCoreConfigLoadPath(&core->config, configPath);
		ConfigurationRead(&gbp->user, configPath);
	}

	gbp->video = calloc(VIDEO_STRIDE * VIDEO_HEIGHT_MAX, sizeof(mColor));
	core->setVideoBuffer(core, gbp->video, VIDEO_STRIDE);
	core->setAudioBufferSize(core, 2048);

	gbp->lux.p = gbp;
	gbp->lux.d.sample = _luxSample;
	gbp->lux.d.readLuminance = _luxRead;
	_luxSample(&gbp->lux.d);

	gbp->rotation.p = gbp;
	gbp->rotation.d.sample = _rotationSample;
	gbp->rotation.d.readTiltX = _readTiltX;
	gbp->rotation.d.readTiltY = _readTiltY;
	gbp->rotation.d.readGyroZ = _readGyroZ;

	gbp->rumble.p = gbp;
	mRumbleIntegratorInit(&gbp->rumble.d);
	gbp->rumble.d.setRumble = _setRumble;

	core->setPeripheral(core, mPERIPH_ROTATION, &gbp->rotation.d);
	core->setPeripheral(core, mPERIPH_RUMBLE, &gbp->rumble.d.d);
#ifdef M_CORE_GBA
	if (core->platform(core) == mPLATFORM_GBA) {
		core->setPeripheral(core, mPERIPH_GBA_LUMINANCE, &gbp->lux.d);
	}
#endif
	return gbp;
}

void gbp_destroy(GBPCore* gbp) {
	if (!gbp) {
		return;
	}
	if (gbp->rewindEnabled) {
		mCoreRewindContextDeinit(&gbp->rewind);
	}
	gbp->core->unloadROM(gbp->core);
	mCoreConfigDeinit(&gbp->core->config);
	gbp->core->deinit(gbp->core);
	ConfigurationDeinit(&gbp->user);
	free(gbp->video);
	free(gbp->romPath);
	free(gbp->configPath);
	free(gbp);
}

/* --- configuration --- */

const char* gbp_config_get(GBPCore* gbp, const char* key) {
	return mCoreConfigGetValue(&gbp->core->config, key);
}

void gbp_config_set(GBPCore* gbp, const char* key, const char* value) {
	mCoreConfigSetValue(&gbp->core->config, key, value);
	ConfigurationSetValue(&gbp->user, NULL, key, value);
}

void gbp_config_set_default(GBPCore* gbp, const char* key, const char* value) {
	mCoreConfigSetDefaultValue(&gbp->core->config, key, value);
}

void gbp_config_unset(GBPCore* gbp, const char* key) {
	ConfigurationClearValue(&gbp->core->config.configTable, NULL, key);
	ConfigurationClearValue(&gbp->user, NULL, key);
}

bool gbp_config_save(GBPCore* gbp) {
	if (!gbp->configPath) {
		return false;
	}
	return ConfigurationWrite(&gbp->user, gbp->configPath);
}

void gbp_config_apply(GBPCore* gbp) {
	struct mCore* core = gbp->core;
	mCoreConfigFreeOpts(&core->opts);
	mCoreConfigMap(&core->config, &core->opts);
	core->loadConfig(core, &core->config);
	core->reloadConfigOption(core, NULL, NULL);
	gbp_rewind_configure(gbp, core->opts.rewindEnable, core->opts.rewindBufferCapacity, core->opts.rewindBufferInterval);
}

/* --- game --- */

bool gbp_start(GBPCore* gbp, const char* savePath) {
	struct mCore* core = gbp->core;
	mCoreConfigMap(&core->config, &core->opts);
	core->loadConfig(core, &core->config);
	if (!mCoreLoadFile(core, gbp->romPath)) {
		return false;
	}
	if (savePath && !mCoreLoadSaveFile(core, savePath, false)) {
		return false;
	}
	core->reset(core);
	gbp_rewind_configure(gbp, core->opts.rewindEnable, core->opts.rewindBufferCapacity, core->opts.rewindBufferInterval);
	return true;
}

int gbp_platform(GBPCore* gbp) {
	return gbp->core->platform(gbp->core);
}

uint32_t gbp_hardware(GBPCore* gbp) {
	uint32_t hw = 0;
#ifdef M_CORE_GBA
	if (gbp->core->platform(gbp->core) == mPLATFORM_GBA) {
		struct GBA* gba = gbp->core->board;
		hw = gba->memory.hw.devices & (HW_RTC | HW_RUMBLE | HW_LIGHT_SENSOR | HW_GYRO | HW_TILT);
	}
#endif
#ifdef M_CORE_GB
	if (gbp->core->platform(gbp->core) == mPLATFORM_GB) {
		struct GB* gb = gbp->core->board;
		switch (gb->memory.mbcType) {
		case GB_MBC7:
			hw |= GBP_HW_TILT;
			break;
		case GB_POCKETCAM:
			hw |= GBP_HW_CAMERA;
			break;
		case GB_MBC5_RUMBLE:
			hw |= GBP_HW_RUMBLE;
			break;
		case GB_MBC3_RTC:
		case GB_HuC3:
			hw |= GBP_HW_RTC;
			break;
		default:
			break;
		}
	}
#endif
	return hw;
}

void gbp_game_title(GBPCore* gbp, char* out, size_t outSize) {
	struct mGameInfo info;
	memset(&info, 0, sizeof(info));
	gbp->core->getGameInfo(gbp->core, &info);
	snprintf(out, outSize, "%s", info.title);
}

void gbp_game_code(GBPCore* gbp, char* out, size_t outSize) {
	struct mGameInfo info;
	memset(&info, 0, sizeof(info));
	gbp->core->getGameInfo(gbp->core, &info);
	snprintf(out, outSize, "%s", info.code);
}

/* --- video, audio, input --- */

void gbp_video_size(GBPCore* gbp, unsigned* width, unsigned* height) {
	gbp->core->currentVideoSize(gbp->core, width, height);
}

const uint32_t* gbp_video_buffer(GBPCore* gbp) {
	return (const uint32_t*) gbp->video;
}

size_t gbp_video_stride(GBPCore* gbp) {
	(void) gbp;
	return VIDEO_STRIDE;
}

void gbp_run_frame(GBPCore* gbp) {
	if (gbp->rewindEnabled && !gbp->rewinding) {
		if (gbp->rewindCounter <= 0) {
			mCoreRewindAppend(&gbp->rewind, gbp->core);
			gbp->rewindCounter = gbp->rewindInterval;
		}
		--gbp->rewindCounter;
	}
	gbp->core->runFrame(gbp->core);
}

double gbp_frame_rate(GBPCore* gbp) {
	return (double) gbp->core->frequency(gbp->core) / (double) gbp->core->frameCycles(gbp->core);
}

unsigned gbp_audio_sample_rate(GBPCore* gbp) {
	return gbp->core->audioSampleRate(gbp->core);
}

size_t gbp_audio_available(GBPCore* gbp) {
	return mAudioBufferAvailable(gbp->core->getAudioBuffer(gbp->core));
}

size_t gbp_audio_read(GBPCore* gbp, int16_t* out, size_t maxFrames) {
	return mAudioBufferRead(gbp->core->getAudioBuffer(gbp->core), out, maxFrames);
}

void gbp_set_keys(GBPCore* gbp, uint32_t keys) {
	gbp->core->setKeys(gbp->core, keys);
}

void gbp_reset(GBPCore* gbp) {
	gbp->core->reset(gbp->core);
	mRumbleIntegratorReset(&gbp->rumble.d);
}

/* --- states and saves --- */

bool gbp_state_save(GBPCore* gbp, const char* path) {
	struct VFile* vf = VFileOpen(path, O_CREAT | O_TRUNC | O_RDWR);
	if (!vf) {
		return false;
	}
	bool ok = mCoreSaveStateNamed(gbp->core, vf, SAVESTATE_RTC | SAVESTATE_METADATA);
	vf->close(vf);
	return ok;
}

bool gbp_state_load(GBPCore* gbp, const char* path) {
	struct VFile* vf = VFileOpen(path, O_RDONLY);
	if (!vf) {
		return false;
	}
	bool ok = mCoreLoadStateNamed(gbp->core, vf, SAVESTATE_RTC);
	vf->close(vf);
	return ok;
}

bool gbp_savedata_export(GBPCore* gbp, const char* path) {
	void* data = NULL;
	size_t size = gbp->core->savedataClone(gbp->core, &data);
	if (!size || !data) {
		free(data);
		return false;
	}
	struct VFile* vf = VFileOpen(path, O_CREAT | O_TRUNC | O_WRONLY);
	bool ok = false;
	if (vf) {
		ok = vf->write(vf, data, size) == (ssize_t) size;
		vf->close(vf);
	}
	free(data);
	return ok;
}

bool gbp_savedata_import(GBPCore* gbp, const char* path) {
	struct VFile* vf = VFileOpen(path, O_RDONLY);
	if (!vf) {
		return false;
	}
	ssize_t size = vf->size(vf);
	bool ok = false;
	if (size > 0) {
		void* data = malloc(size);
		if (vf->read(vf, data, size) == size) {
			ok = gbp->core->savedataRestore(gbp->core, data, size, true);
		}
		free(data);
	}
	vf->close(vf);
	return ok;
}

/* --- rewind --- */

void gbp_rewind_configure(GBPCore* gbp, bool enable, int capacity, int interval) {
	if (gbp->rewindEnabled) {
		mCoreRewindContextDeinit(&gbp->rewind);
		gbp->rewindEnabled = false;
	}
	if (enable && capacity > 0) {
		mCoreRewindContextInit(&gbp->rewind, capacity, true);
		gbp->rewindEnabled = true;
		gbp->rewindInterval = interval > 0 ? interval : 1;
		gbp->rewindCounter = 0;
	}
}

bool gbp_rewind_step(GBPCore* gbp) {
	if (!gbp->rewindEnabled) {
		return false;
	}
	return mCoreRewindRestore(&gbp->rewind, gbp->core, 1);
}

void gbp_set_rewinding(GBPCore* gbp, bool rewinding) {
	gbp->rewinding = rewinding;
	if (!rewinding) {
		gbp->rewindCounter = 0;
	}
}

/* --- cheats --- */

static struct mCheatSet* _cheatSet(GBPCore* gbp, size_t index) {
	struct mCheatDevice* device = gbp->core->cheatDevice(gbp->core);
	if (!device || index >= mCheatSetsSize(&device->cheats)) {
		return NULL;
	}
	return *mCheatSetsGetPointer(&device->cheats, index);
}

bool gbp_cheats_load(GBPCore* gbp, const char* path) {
	struct mCheatDevice* device = gbp->core->cheatDevice(gbp->core);
	if (!device) {
		return false;
	}
	struct VFile* vf = VFileOpen(path, O_RDONLY);
	if (!vf) {
		return false;
	}
	mCheatDeviceClear(device);
	bool ok = mCheatParseFile(device, vf);
	vf->close(vf);
	return ok;
}

bool gbp_cheats_save(GBPCore* gbp, const char* path) {
	struct mCheatDevice* device = gbp->core->cheatDevice(gbp->core);
	if (!device) {
		return false;
	}
	struct VFile* vf = VFileOpen(path, O_CREAT | O_TRUNC | O_WRONLY);
	if (!vf) {
		return false;
	}
	bool ok = mCheatSaveFile(device, vf);
	vf->close(vf);
	return ok;
}

size_t gbp_cheats_count(GBPCore* gbp) {
	struct mCheatDevice* device = gbp->core->cheatDevice(gbp->core);
	return device ? mCheatSetsSize(&device->cheats) : 0;
}

void gbp_cheats_name(GBPCore* gbp, size_t index, char* out, size_t outSize) {
	struct mCheatSet* set = _cheatSet(gbp, index);
	snprintf(out, outSize, "%s", set && set->name ? set->name : "");
}

bool gbp_cheats_enabled(GBPCore* gbp, size_t index) {
	struct mCheatSet* set = _cheatSet(gbp, index);
	return set && set->enabled;
}

void gbp_cheats_set_enabled(GBPCore* gbp, size_t index, bool enabled) {
	struct mCheatSet* set = _cheatSet(gbp, index);
	if (!set) {
		return;
	}
	set->enabled = enabled;
	if (set->refresh) {
		set->refresh(set, gbp->core->cheatDevice(gbp->core));
	}
}

void gbp_cheats_remove(GBPCore* gbp, size_t index) {
	struct mCheatSet* set = _cheatSet(gbp, index);
	if (!set) {
		return;
	}
	mCheatRemoveSet(gbp->core->cheatDevice(gbp->core), set);
	mCheatSetDeinit(set);
}

bool gbp_cheats_add(GBPCore* gbp, const char* name, const char* codes) {
	struct mCheatDevice* device = gbp->core->cheatDevice(gbp->core);
	if (!device) {
		return false;
	}
	struct mCheatSet* set = device->createSet(device, name);
	bool any = false;
	char* copy = strdup(codes);
	char* saveptr = NULL;
	for (char* line = strtok_r(copy, "\r\n", &saveptr); line; line = strtok_r(NULL, "\r\n", &saveptr)) {
		while (*line == ' ' || *line == '\t') {
			++line;
		}
		if (!*line) {
			continue;
		}
		if (mCheatAddLine(set, line, 0)) {
			any = true;
		}
	}
	free(copy);
	if (!any) {
		mCheatSetDeinit(set);
		return false;
	}
	mCheatAddSet(device, set);
	return true;
}

bool gbp_savedata_reload(GBPCore* gbp, const char* path) {
	return mCoreLoadSaveFile(gbp->core, path, false);
}

/* --- Game Boy palettes --- */

size_t gbp_gb_palette_count(void) {
#ifdef M_CORE_GB
	const struct GBColorPreset* presets;
	return GBColorPresetList(&presets);
#else
	return 0;
#endif
}

const char* gbp_gb_palette_name(size_t index) {
#ifdef M_CORE_GB
	const struct GBColorPreset* presets;
	size_t count = GBColorPresetList(&presets);
	return index < count ? presets[index].name : NULL;
#else
	return NULL;
#endif
}

void gbp_gb_palette_apply(GBPCore* gbp, size_t index) {
#ifdef M_CORE_GB
	const struct GBColorPreset* presets;
	size_t count = GBColorPresetList(&presets);
	if (index >= count) {
		return;
	}
	char key[16];
	for (int i = 0; i < 12; ++i) {
		snprintf(key, sizeof(key), "gb.pal[%d]", i);
		char value[16];
		snprintf(value, sizeof(value), "%u", presets[index].colors[i] & 0xFFFFFF);
		gbp_config_set(gbp, key, value);
	}
	gbp->core->reloadConfigOption(gbp->core, "gb.pal", NULL);
#endif
}

/* --- sensors --- */

void gbp_set_light_level(GBPCore* gbp, int level) {
	if (level < 0) {
		level = 0;
	} else if (level > 10) {
		level = 10;
	}
	gbp->luxLevel = level;
}

int gbp_light_level(GBPCore* gbp) {
	return gbp->luxLevel;
}

void gbp_set_tilt(GBPCore* gbp, float x, float y) {
	gbp->tiltX = x;
	gbp->tiltY = y;
}

float gbp_rumble_level(GBPCore* gbp) {
	return gbp->rumbleLevel;
}
